rules.logic:
element.style.display = 'none'

var parent = element.parentElement;
if (!parent || element.dataset.gridInjected) return;
element.dataset.gridInjected = 'true';

var grid = document.createElement('div');
grid.className = 'm-auto mt-6 mb-12 max-w-[760px] md:px-6 lg:max-w-[1000px] lg:px-6';
grid.setAttribute('data-custom-grid', 'true');

var heading = document.createElement('h2');
heading.className = 'text-xl font-bold mb-4 text-gray-800 dark:text-ymp-uh-grey-hair';
heading.textContent = 'Browse by Category';
grid.appendChild(heading);

var categories = [
  { name: 'News', icon: '📰', url: 'https://news.yahoo.com/' },
  { name: 'Finance', icon: '💰', url: 'https://finance.yahoo.com/' },
  { name: 'Sports', icon: '⚽', url: 'https://sports.yahoo.com/' },
  { name: 'Weather', icon: '🌤️', url: 'https://weather.yahoo.com/' },
  { name: 'Entertainment', icon: '🎬', url: 'https://entertainment.yahoo.com/' },
  { name: 'Tech', icon: '💻', url: 'https://tech.yahoo.com/' },
  { name: 'Health', icon: '❤️', url: 'https://health.yahoo.com/' },
  { name: 'Shopping', icon: '🛒', url: 'https://shopping.yahoo.com/' },
  { name: 'Travel', icon: '✈️', url: 'https://travel.yahoo.com/' },
  { name: 'Lifestyle', icon: '🏠', url: 'https://life.yahoo.com/' },
  { name: 'Autos', icon: '🚗', url: 'https://autos.yahoo.com/' },
  { name: 'Gaming', icon: '🎮', url: 'https://gaming.yahoo.com/' },
];

var gridContainer = document.createElement('div');
gridContainer.className = 'grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-4';

categories.forEach(function(cat) {
  var btn = document.createElement('a');
  btn.href = cat.url;
  btn.className = 'flex flex-col items-center justify-center rounded-xl bg-white dark:bg-uds-secondary-dark border border-ymp-uh-dirty-seagull dark:border-gray-700 p-6 hover:border-purple-500 hover:shadow-lg transition-all duration-200 cursor-pointer text-decoration-none';
  btn.setAttribute('data-category-btn', cat.name.toLowerCase());

  var icon = document.createElement('div');
  icon.className = 'text-4xl mb-3';
  icon.textContent = cat.icon;
  btn.appendChild(icon);

  var label = document.createElement('span');
  label.className = 'font-medium text-gray-800 dark:text-ymp-uh-grey-hair text-base';
  label.textContent = cat.name;
  btn.appendChild(label);

  gridContainer.appendChild(btn);
});

grid.appendChild(gridContainer);
parent.insertBefore(grid, element.nextSibling);
